insert into public.concepts(id,title) values(1,'Why does a backend exist at all?');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(1,1,'A quiz app checks answers in the browser, then sends {"score": 4} to the server, which saves it. Using DevTools, a learner changes the request to {"score": 10} before it’s sent. What score gets saved, and why?','10','["10", "ten"]'::jsonb,null,'[]'::jsonb,'The server trusted a result calculated on the user’s machine. The answers should be checked on the server.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(2,1,'A weather app calls a paid weather API straight from the browser, with the API key in the JavaScript. The developer’s monthly bill goes from $5 to $400, but the app’s traffic hasn’t changed. What’s the most likely cause?','someone copied the key','["someone copied the key"]'::jsonb,'[["key"], ["copied", "stolen", "leaked", "someone else using", "scraped"]]'::jsonb,'[]'::jsonb,'They are using it outside the app. The key should live on a backend that calls the API for the app.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(3,1,'A team poll app stores votes in each user’s localStorage. Five teammates vote “Pizza.” Then a sixth teammate opens the app on their own laptop. How many votes for “Pizza” do they see, and why?','0','["0", "zero", "none"]'::jsonb,null,'[]'::jsonb,'Each vote is stored only in that voter’s browser. A backend and database are needed to collect votes in one shared place.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(4,1,'A shop app puts its database password inside the webpage code. The database holds the orders of 500 customers. A curious visitor copies the password and connects to the database. How many customers’ orders can they read?','500','["500", "five hundred", "all", "all 500", "everyone''s", "everyone", "all of them"]'::jsonb,null,'[]'::jsonb,'The password works for whoever has it, so the visitor sees everything the app can see. Only the backend should hold the database password and hand each user only their own data.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(5,1,'A course app hides the “Download certificate” button in the browser unless user.paid === true. The certificate file is served from a public URL. A learner who hasn’t paid opens DevTools. They change one value in DevTools and the button appears. Which value do they change?','user.paid','["user.paid", "paid", "paid flag"]'::jsonb,null,'[]'::jsonb,'Changing user.paid makes the button appear, because the check runs in the browser. The payment check and the file should both sit behind the backend.');
insert into public.concepts(id,title) values(2,'What does one API call carry?');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(6,2,'Priya tells a chatbot her name. For her next question, the app sends only “What is my name?” and leaves out her earlier message. Can the chatbot know her name from this new request alone?','no','["no", "can''t know", "cannot know", "doesn''t know", "does not know", "won''t know", "will not know", "can''t remember", "cannot remember", "not included", "not sent", "left out", "leaves out"]'::jsonb,null,'[]'::jsonb,'The new request does not include Priya’s name. The app must send the earlier message again for the chatbot to use it.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(7,2,'A developer’s server calls the LLM API but forgets the Authorization header. The body is correct. What status code comes back, and why?','401','["401"]'::jsonb,null,'[]'::jsonb,'The key has to travel with every call, because the API doesn’t remember that this server called before.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(8,2,'A FastAPI server defines @app.post("/diagnose"). A learner opens http://localhost:8000/diagnose in the browser address bar. What happens, and why?','405','["405", "method not allowed"]'::jsonb,null,'["\\bget\\b.{0,35}\\b(?:instead of|rather than|not)\\b.{0,20}\\bpost\\b", "\\b(?:sends?|sending|makes?|making|uses?|using)\\b.{0,20}\\bget\\b.{0,90}\\b(?:expects?|accepts?|requires?|only supports?)\\b.{0,20}\\bpost\\b"]'::jsonb,'Typing a URL in the browser address bar sends GET, but /diagnose only accepts POST, so FastAPI responds with 405 Method Not Allowed.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(9,2,'A server expects a problem report in a field named "description". The app sends it in a field named "desc" instead. Which field name should the app use so the server can read the report?','description','["description"]'::jsonb,null,'[]'::jsonb,'The field name must match what the server expects. Sending "desc" does not provide the required "description" field.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(10,2,'An app wants an AI to translate “Hello” into Hindi. What should it send in one request: just “Hello”, or “Hello” together with the instruction “Translate into Hindi”?','both','["both", "together", "sentence and the instruction", "instruction and the sentence", "hello and translate into hindi"]'::jsonb,null,'[]'::jsonb,'The AI needs both what to do and the text to do it to in the same request.');
insert into public.concepts(id,title) values(3,'Why can’t the key live in the browser?');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(11,3,'A developer minifies and obfuscates their React bundle so the key looks like random characters spread across the file. A visitor opens the Network tab and sends one chat message. In which part of the request can they read the key in plain text?','authorization','["authorization", "header", "headers"]'::jsonb,null,'[]'::jsonb,'The key has to be sent in usable form in the request’s Authorization header, so it shows up in plain text in the Network tab whatever the bundle looks like.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(12,3,'A developer puts the OpenAI key inside their webpage’s JavaScript. A stranger copies it and uses it in their own script to make 1,000 AI calls. Whose account is billed for those 1,000 calls?','developer','["developer", "developers", "app owner", "mine"]'::jsonb,null,'[]'::jsonb,'The key isn’t tied to the app. The AI provider bills the key’s owner for every call made with it, from anywhere. That’s why the key must stay on the server.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(13,3,'The site runs on HTTPS, and the developer says “the key is encrypted in transit, so it’s safe in the frontend.” A visitor opens DevTools on their own laptop. In which DevTools tab do they find the key in plain text?','network','["network", "sources"]'::jsonb,null,'[]'::jsonb,'HTTPS protects data between the browser and the server from other people on the network. The visitor’s own browser decrypts everything, so they can see it.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(14,3,'A key was in the frontend for a week. The developer removes it from the code and redeploys. Two days later, the provider dashboard still shows usage the app didn’t make. Why, and what should they have done?','revoke','["revoke", "revoked", "revoking", "rotate", "rotated", "rotating", "regenerate", "regenerated", "regenerating", "new key"]'::jsonb,null,'[]'::jsonb,'Someone copied the key while it was exposed, and it’s still valid. The new key should live only on the backend.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(15,3,'A developer moves the key to their backend. The browser now sends POST /chat with {"message": "..."}, and the backend calls the LLM. A visitor opens the Network tab. On which machine is the key added to the LLM request?','server','["server", "backend"]'::jsonb,null,'[]'::jsonb,'They see the request to /chat with their own message and the reply. The key is added on the server and never goes to the browser.');
insert into public.concepts(id,title) values(4,'Why does the app forget without storage?');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(16,4,'A React app keeps a counter in useState. A user clicks "+1" seven times, then refreshes the page. What does the counter show, and why?','0','["0", "zero"]'::jsonb,null,'[]'::jsonb,'Component state lives only in the page’s memory, and a refresh wipes it. It would need to be saved to storage and loaded on startup.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(17,4,'An app saves 10 attempts in temporary memory. The server restarts. How many attempts remain?','0','["0", "zero", "none"]'::jsonb,null,'[]'::jsonb,'Temporary memory is cleared when the server restarts. Save attempts in a database to keep them.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(18,4,'An app runs on two server instances behind a load balancer and stores each learner’s progress in RAM. A learner completes 3 steps, and all those requests go to instance A. Their next request goes to instance B. How many completed steps does instance B find for them?','0','["0", "zero"]'::jsonb,null,'[]'::jsonb,'Each instance has its own RAM, so B never saw the 3 steps. Shared progress has to go in a database that both instances read from.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(19,4,'An app sends only the latest chat message to the AI. Can the AI see the earlier messages?','no','["no", "cannot see", "can''t see", "does not see", "doesn''t see", "not sent", "not included"]'::jsonb,null,'[]'::jsonb,'The AI can only use the messages included in this request. Saving older messages does not automatically send them to the AI.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(20,4,'You save three notes in your browser. Will they appear in a new Incognito window?','no','["no", "will not", "won''t", "zero", "0", "none"]'::jsonb,null,'[]'::jsonb,'A new Incognito session has separate browser storage, so it cannot read the notes saved in the normal browser.');
insert into public.concepts(id,title) values(5,'Why does the pointer sit on the many side?');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(21,5,'Your app has a learners table and an attempts table. One learner makes many attempts, and each attempt belongs to one learner. Which table gets the pointer column?','attempts','["attempts"]'::jsonb,null,'[]'::jsonb,'Each attempt has exactly one learner, so the attempts table holds one value: learner_id.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(22,5,'Two requests each add an ID to the same old list. The second save overwrites the first. How many new IDs survive?','1','["1", "one", "only the second", "only the last"]'::jsonb,null,'[]'::jsonb,'Only the ID added by the second request survives. Its save overwrites the first request’s version of the list.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(23,5,'Priya’s email appears in six records. Only one is updated with her new email. How many different emails are now stored?','2','["2", "two"]'::jsonb,null,'[]'::jsonb,'Five records still contain the old email, and one contains the new email: two different addresses.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(24,5,'In Concept Check, the LLM names one gap per session, and a learner may submit up to 2 retries that answer that gap. Which table holds the pointer?','retries','["retries"]'::jsonb,null,'[]'::jsonb,'Each retry answers exactly one gap, so the retries table holds gap_id, while a gap can have many retries.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(25,5,'Students can join many courses. Courses can have many students. Should a separate table record who joined which course?','yes','["yes", "separate table", "join table", "junction table", "enrollments", "student_courses"]'::jsonb,null,'[]'::jsonb,'A separate table stores one student and one course per row. This supports many students joining many courses.');
insert into public.concepts(id,title) values(6,'Why is history a row, not a cell?');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(26,6,'Concept Check stores learners.last_case_result, updated after each new case. A learner fails the first case, gets the follow-up, then passes the second case. How many case results can the database show?','1','["1", "one"]'::jsonb,null,'[]'::jsonb,'Only the latest result is stored: the second case’s pass overwrote the first case’s fail.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(27,6,'An app keeps only the latest delivery status. After “placed”, “shipped”, and “delivered”, which status remains?','delivered','["delivered"]'::jsonb,null,'[]'::jsonb,'Each new status replaces the previous one. Only delivered remains because no status history was saved.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(28,6,'A wallet app stores only accounts.balance and updates it on every payment. A user’s balance dropped from $200 to $140, and they want to know which charge caused it. How many individual charges can the app list for them?','0','["0", "zero", "none"]'::jsonb,null,'[]'::jsonb,'Only the current balance is stored, so the individual charges are lost. A transactions table with one row per charge would show them, and the balance can be calculated from those rows.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(29,6,'A shirt cost $20 when bought and costs $25 now. An invoice uses today’s price. What price does it show?','25','["25", "twenty five"]'::jsonb,null,'[]'::jsonb,'The invoice reads today’s price of $25. The app would need to save the purchase price to show the original $20.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(30,6,'An app keeps one latest sentence per learner. With 30 learners, how many sentences are saved?','30','["30", "thirty"]'::jsonb,null,'[]'::jsonb,'There is one saved sentence for each of the 30 learners, so there are 30 sentences in total.');
insert into public.concepts(id,title) values(7,'How do you decide where a piece lives?');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(31,7,'In Concept Check, each new case has a known answer. A developer sends the case and its answer to the browser, so the browser can show “Correct!” instantly. Where should the answer live, and why?','backend or private database','["server", "backend", "database", "private database", "db"]'::jsonb,null,'[]'::jsonb,'The answer key can be stored on the backend or in a private database that only backend grading code can read. Learners must not receive it in the browser, where it could be inspected in DevTools. The browser sends the learner’s answer for grading.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(32,7,'A developer asks the LLM, “Based on this retry, has the learner understood now? Reply PASS or FAIL,” and saves the result. Where should the pass/fail decision live, and why?','code','["code", "deterministic", "not the llm", "not ai"]'::jsonb,null,'[]'::jsonb,'Code checks the new case against the pre-written answer key. Pass/fail is a fixed rule, and letting the AI decide understanding is the no-go.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(33,7,'A learner is halfway through typing their explanation and hasn’t submitted it. A developer wants to save every keystroke to the database “just in case.” Where should the in-progress text live, and why?','browser','["browser", "component state", "localstorage"]'::jsonb,null,'[]'::jsonb,'It’s harmless and not needed by anyone else yet. It goes to the server only when submitted.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(34,7,'Should a learner’s email be saved once in their learner record or repeated in every attempt?','once','["once", "learner record", "learners record", "learners table", "learner table"]'::jsonb,null,'[]'::jsonb,'The email describes the learner. Store it once in the learner record and link attempts using the learner ID.');
insert into public.case_questions(id,concept_id,prompt,answer_core,aliases,required_groups,patterns,answer_reason) values(35,7,'The list of 7 ideas and the answer key are both fixed lists shipped in code. The developer sends both to the browser. Which one should not be sent?','answer key','["answer key"]'::jsonb,null,'[]'::jsonb,'Learners need to see the ideas list to pick one. Seeing the answer key lets them pass without reasoning. The same kind of data goes in different places because of one question: can the user be trusted to see it?');
